output_text:
[
  {
    "id": "return_cart_to_front_bay",
    "text": "A shopper who uses a cart is obliged to return it to the front cart-return bay before leaving the store.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_bay": "at(0,1)",
        "cart_parked_in_front_bay": "cartAt(0,1)"
      },
      "events": {
        "return_cart_to_front_bay": {
          "pre": {
            "and": [
              "front_cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_front_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_front_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "It is prohibited to exit the supermarket while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "pushing_cart"
        ]
      }
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "A shopper may exit only after the cart has been parked in the front return bay.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_returned"
          }
        ]
      }
    }
  },
  {
    "id": "do_not_abandon_cart_elsewhere",
    "text": "Leaving a cart anywhere except the designated front return bay is prohibited.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_somewhere": {
          "pre": {
            "and": [
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart_somewhere",
          {
            "not": "front_cart_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "must_take_entrance_cart",
    "text": "At the start of a shopping trip, the shopper is obliged to collect the available cart from the entrance cart station.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "pick_up_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pick_up_entrance_cart"
    }
  },
  {
    "id": "items_must_go_in_cart",
    "text": "Picking up shelf items without a cart is prohibited, so required items must be placed into the cart rather than carried loose by hand.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "take_shelf_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "take_shelf_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "It is prohibited to carry grocery items by hand inside the store.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "checkout_lanes_are_cart_free_eastbound",
    "text": "Carts may not be pushed eastward through the front checkout or exit lanes after reaching the return area.",
    "abstraction": {
      "state_properties": {
        "front_checkout_lane": {
          "or": [
            "at(0,1)",
            "at(1,1)",
            "at(2,1)",
            "at(3,1)",
            "at(4,1)",
            "at(5,1)",
            "at(6,1)",
            "at(7,1)",
            "at(8,1)",
            "at(9,1)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "push_cart_east_in_checkout_lane": {
          "pre": {
            "and": [
              "front_checkout_lane",
              "pushing_cart",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_east_in_checkout_lane"
    }
  }
]
